void project_clear(struct em_project *project)
{
	size_t i, j;
	for (i = 0; i < project->count; i++) {
		struct node *node = project->nodes + i;
		for (j = 0; j < node->direct_count; j++)
			free(node->base_names[j]);
		free(node->base_names);
		free(node->direct);
		free(node->name);
		free(node->source.data);
		free(node->output.data);
		if (node->temporary)
			remove(node->temporary);
		free(node->temporary);
		free((char *)node->path);
	}
	free(project->nodes);
	free(project->reach);
	*project = (struct em_project){ 0 };
}

static int project_update(struct em_project *project, const struct project_request *request,
	const unsigned char *targets, const struct node *host)
{
	size_t i;
	for (i = 0; i < project->count; i++) {
		struct node *node = project->nodes + i;
		if (!(targets && !targets[i] ? node_erase(node) : node_generate(project, i)))
			return node_diagnostic(node, 0, "cannot generate constructor");
		if (node->output.length == node->source.length &&
		    !memcmp(node->output.data, node->source.data, node->source.length))
			continue;
		printf("%s: constructor %s\n", node->path, request->write ? "update planned" : "would change");
		if (request->write && !file_prepare(node->path, &node->output, &node->temporary))
			return node_diagnostic(node, 0, "cannot prepare output; no files committed");
	}
	/* Recheck all originals before the first commit to catch ordinary edits. */
	if (!request->write)
		return 1;
	if (host) {
		struct text current = { 0 };
		int same = file_read(host->path, &current) &&
			current.length == host->source.length &&
			!memcmp(current.data, host->source.data, current.length);
		free(current.data);
		if (!same)
			return node_diagnostic(host, 0, "host changed during generation; no files committed");
	}
	for (i = 0; i < project->count; i++) {
		struct node *node = project->nodes + i;
		struct text current = { 0 };
		int same = file_read(node->path, &current) &&
			current.length == node->source.length &&
			!memcmp(current.data, node->source.data, current.length);
		free(current.data);
		if (!same)
			return node_diagnostic(node, 0, "source changed during generation; no files committed");
	}
	for (i = 0; i < project->count; i++) {
		struct node *node = project->nodes + i;
		if (!node->temporary)
			continue;
		if (!file_commit(node->path, node->temporary, 1))
			return node_diagnostic(node, 0, "cannot replace file; earlier reported commits remain (rerun after fixing the error)");
		printf("%s: committed\n", node->path);
		free(node->temporary);
		node->temporary = NULL;
	}
	return 1;
}

int project_execute(struct em_project *project, const struct project_request *request)
{
	struct node host = { 0 };
	struct text path = { 0 };
	unsigned char *targets = NULL;
	int ok = 0;
	if (!request || project->nodes)
		return 0;
	if (request->directory) {
		if (!text_printf(&path, "%s/ho.c", request->directory))
			goto done;
		if (!file_regular(path.data)) {
			path.length = 0;
			if (!text_printf(&path, "%s/host.c", request->directory))
				goto done;
		}
		host.path = path.data;
		if (!file_read(host.path, &host.source)) {
			node_diagnostic(&host, 0, "cannot read host source (ho.c or host.c)");
			goto done;
		}
		if (!project_collect(project, request->directory)) {
			fprintf(stderr, "%s: cannot collect marked node sources\n", request->directory);
			goto done;
		}
	} else {
		if (request->count < 1 || !request->paths)
			goto done;
		project->nodes = calloc((size_t)request->count, sizeof(*project->nodes));
		if (!project->nodes)
			goto done;
		project->count = (size_t)request->count;
		for (size_t i = 0; i < project->count; i++) {
			struct text owned = { 0 };
			if (!text_append(&owned, request->paths[i], strlen(request->paths[i])))
				goto done;
			project->nodes[i].path = owned.data;
		}
	}
	for (size_t i = 0; i < project->count; i++)
		if (!node_parse(project->nodes + i))
			goto done;
	if (!graph_validate(project))
		goto done;
	if (request->directory) {
		targets = calloc(project->count, 1);
		if (!targets || !host_targets(project, &host, targets))
			goto done;
	}
	ok = project_update(project, request, targets, request->directory ? &host : NULL);
done:
	free(targets);
	free(host.source.data);
	free(path.data);
	return ok;
}

static int project_open(struct object *self, const struct vr *caller_context)
{
	OBS_OBJECT_OPEN_;
	return R_P;
}

static int project_close(struct object *self, const struct vr *caller_context)
{
	OBS_OBJECT_CLOSE_;
	project_clear(self->members);
	return R_P;
}

static int project_interact2(struct object *self, unsigned int action,
	unsigned char *input_stream, unsigned int quantity,
	const struct vr *caller_context)
{
	if (action == AC2_PROJECT_RUN) {
		struct project_request request;
		if (!input_stream || quantity != sizeof(request))
			return RN_INVALIDARG;
		memcpy(&request, input_stream, sizeof(request));
		return project_execute(self->members, &request) ? R_P : R_N;
	}
	SBO_OBJECT_INTERACT2;
}

