void tog_project(struct object *object)
{
	object->open = project_open;
	object->input = project_input;
	object->output = project_output;
	object->io_put = project_io_put;
	object->interact0 = project_interact0;
	object->interact1 = project_interact1;
	object->interact2 = project_interact2;
	object->interact3 = project_interact3;
	object->close = project_close;
}
